-- A7 Credit Risk fact tables and curated Aura views (spec sections 8.5, 8.6).
-- No automated approval, decline, pricing, or adverse-action field is
-- generated by Aura anywhere in this schema: `review_status` and
-- `was_manual_review` describe operational workflow state only, and
-- `credit_evidence` records observed metrics, not a decision. The pending
-- vs. booked comparison in `aa_portfolio_concentration` is explicitly
-- illustrative, per spec section 8.7. The "latest snapshot" lookup in that
-- view is a GROUP BY + join derived table rather than a correlated
-- subquery, since SingleStore's distributed query engine cannot always
-- rewrite a correlated subquery into a join.

DROP VIEW IF EXISTS aa_portfolio_concentration;

DROP VIEW IF EXISTS aa_credit_application_evidence;

DROP VIEW IF EXISTS aa_credit_operations;

DROP TABLE IF EXISTS portfolio_exposure_snapshot;

DROP TABLE IF EXISTS credit_evidence;

DROP TABLE IF EXISTS credit_application;

CREATE TABLE credit_application (
    run_id            BIGINT        NOT NULL,
    application_id    VARCHAR(40)   NOT NULL,
    customer_id       VARCHAR(24)   NOT NULL,
    product_id        VARCHAR(24)   NOT NULL,
    channel           VARCHAR(24)   NOT NULL,
    submitted_at      DATETIME(6)   NOT NULL,
    requested_amount  DECIMAL(18,2) NOT NULL,
    industry_code     VARCHAR(16)   NOT NULL,
    geography_id      VARCHAR(8)    NOT NULL,
    review_status     VARCHAR(24)   NOT NULL,
    was_manual_review BOOL          NOT NULL,
    decision_time     DATETIME(6)   NULL,
    scenario_id       VARCHAR(64)   NULL,
    SHARD KEY (run_id, application_id),
    SORT KEY (run_id, submitted_at)
);

CREATE TABLE credit_evidence (
    run_id               BIGINT        NOT NULL,
    evidence_id          VARCHAR(40)   NOT NULL,
    application_id       VARCHAR(40)   NOT NULL,
    source_type          VARCHAR(32)   NOT NULL,
    metric_name          VARCHAR(48)   NOT NULL,
    metric_value         DECIMAL(18,4) NOT NULL,
    observed_at          DATETIME(6)   NOT NULL,
    verification_status  VARCHAR(24)   NOT NULL,
    provenance_ref       VARCHAR(128)  NOT NULL,
    scenario_id          VARCHAR(64)   NULL,
    SHARD KEY (run_id, evidence_id),
    SORT KEY (run_id, observed_at)
);

CREATE TABLE portfolio_exposure_snapshot (
    run_id              BIGINT        NOT NULL,
    as_of_time          DATETIME(6)   NOT NULL,
    facility_id         VARCHAR(40)   NOT NULL,
    entity_id           VARCHAR(24)   NOT NULL,
    industry_code       VARCHAR(16)   NOT NULL,
    geography_id        VARCHAR(8)    NOT NULL,
    existing_risk_grade VARCHAR(8)    NOT NULL,
    outstanding_amount  DECIMAL(18,2) NOT NULL,
    committed_amount    DECIMAL(18,2) NOT NULL,
    SHARD KEY (run_id, facility_id),
    SORT KEY (run_id, as_of_time)
);

CREATE VIEW aa_credit_operations AS
SELECT
    ca.product_id AS product_id,
    dp.product_name AS product_name,
    ca.channel AS channel,
    DATE(ca.submitted_at) AS submitted_date,
    COUNT(*) AS application_count,
    SUM(CASE WHEN ca.was_manual_review = 1 THEN 1 ELSE 0 END) AS manual_review_count,
    SUM(CASE WHEN ca.was_manual_review = 1 THEN 1 ELSE 0 END) / COUNT(*) AS manual_review_rate,
    AVG(TIMESTAMPDIFF(HOUR, ca.submitted_at, ca.decision_time)) AS avg_hours_to_decision,
    SUM(ca.requested_amount) AS requested_amount_total
FROM credit_application ca
JOIN demo_active_run ar ON ar.singleton_id = 1 AND ar.run_id = ca.run_id
JOIN dim_product dp ON dp.run_id = ca.run_id AND dp.product_id = ca.product_id
WHERE ca.submitted_at <= ar.logical_time
GROUP BY ca.product_id, dp.product_name, ca.channel, DATE(ca.submitted_at);

CREATE VIEW aa_credit_application_evidence AS
SELECT
    ce.evidence_id AS evidence_id,
    ce.application_id AS application_id,
    ca.customer_id AS customer_id,
    ca.product_id AS product_id,
    ce.source_type AS source_type,
    ce.metric_name AS metric_name,
    ce.metric_value AS metric_value,
    ce.observed_at AS observed_at,
    ce.verification_status AS verification_status,
    ce.provenance_ref AS provenance_ref
FROM credit_evidence ce
JOIN credit_application ca ON ca.run_id = ce.run_id AND ca.application_id = ce.application_id
JOIN demo_active_run ar ON ar.singleton_id = 1 AND ar.run_id = ce.run_id
WHERE ce.observed_at <= ar.logical_time;

CREATE VIEW aa_portfolio_concentration AS
SELECT
    pes.industry_code AS industry_code,
    pes.geography_id AS geography_id,
    pes.existing_risk_grade AS existing_risk_grade,
    SUM(pes.outstanding_amount) AS booked_outstanding_amount,
    SUM(pes.committed_amount) AS booked_committed_amount,
    SUM(pes.outstanding_amount) / SUM(t.total_outstanding) AS concentration_share,
    COALESCE(p.pending_amount, 0) AS pending_amount,
    (SUM(pes.outstanding_amount) + COALESCE(p.pending_amount, 0))
        / (SUM(t.total_outstanding) + COALESCE(p.pending_amount, 0)) AS pro_forma_concentration_share
FROM portfolio_exposure_snapshot pes
JOIN demo_active_run ar ON ar.singleton_id = 1 AND ar.run_id = pes.run_id
JOIN (
    -- Latest snapshot time at or before the logical clock. A join-based
    -- "latest row" pattern instead of a correlated subquery, since
    -- SingleStore's distributed query engine cannot always rewrite a
    -- correlated subquery into a join.
    SELECT pes3.run_id, MAX(pes3.as_of_time) AS latest_as_of_time
    FROM portfolio_exposure_snapshot pes3
    JOIN demo_active_run ar3
        ON ar3.singleton_id = 1 AND ar3.run_id = pes3.run_id AND pes3.as_of_time <= ar3.logical_time
    GROUP BY pes3.run_id
) latest ON latest.run_id = pes.run_id AND latest.latest_as_of_time = pes.as_of_time
JOIN (
    SELECT run_id, as_of_time, SUM(outstanding_amount) AS total_outstanding
    FROM portfolio_exposure_snapshot
    GROUP BY run_id, as_of_time
) t ON t.run_id = pes.run_id AND t.as_of_time = pes.as_of_time
LEFT JOIN (
    SELECT run_id, industry_code, geography_id, SUM(requested_amount) AS pending_amount
    FROM credit_application
    WHERE review_status <> 'decided'
    GROUP BY run_id, industry_code, geography_id
) p ON p.run_id = pes.run_id AND p.industry_code = pes.industry_code AND p.geography_id = pes.geography_id
WHERE pes.as_of_time <= ar.logical_time
GROUP BY pes.industry_code, pes.geography_id, pes.existing_risk_grade, p.pending_amount;
